-- Phase 4: durable, tenant-scoped workflow definitions, immutable versions, runs, step runs, approvals and events.
CREATE TABLE IF NOT EXISTS workflows (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,key TEXT NOT NULL,name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),description TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','paused','archived')),created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE (clinic_id,key));
CREATE TABLE IF NOT EXISTS workflow_versions (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE,version INTEGER NOT NULL CHECK (version > 0),definition JSONB NOT NULL,activated_at TIMESTAMPTZ,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workflow_id,version));
CREATE TABLE IF NOT EXISTS workflow_runs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE RESTRICT,workflow_version_id TEXT NOT NULL REFERENCES workflow_versions(id) ON DELETE RESTRICT,status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','waiting_for_approval','completed','failed','escalated','cancelled')),trigger_type TEXT NOT NULL,trigger_key TEXT,actor_id TEXT,request_id TEXT,idempotency_key TEXT NOT NULL,context JSONB NOT NULL DEFAULT '{}'::jsonb,result JSONB,failure_class TEXT,retry_count INTEGER NOT NULL DEFAULT 0 CHECK (retry_count >= 0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(clinic_id,workflow_id,idempotency_key));
CREATE TABLE IF NOT EXISTS workflow_step_runs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,step_key TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK (ordinal >= 0),status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','waiting_for_approval','completed','failed','escalated','cancelled')),input JSONB,output JSONB,error_class TEXT,attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workflow_run_id,step_key));
CREATE TABLE IF NOT EXISTS workflow_approvals (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,workflow_step_run_id TEXT REFERENCES workflow_step_runs(id) ON DELETE CASCADE,requested_action JSONB NOT NULL,risk_level TEXT NOT NULL CHECK (risk_level IN ('READ','LOW_RISK_WRITE','HIGH_RISK_WRITE','EXTERNAL_SIDE_EFFECT')),status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','expired','cancelled')),requested_by TEXT NOT NULL,decided_by TEXT,expires_at TIMESTAMPTZ,decided_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_events (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,clinic_id TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,workflow_run_id TEXT REFERENCES workflow_runs(id) ON DELETE CASCADE,event_type TEXT NOT NULL,actor_id TEXT,request_id TEXT,aggregate_type TEXT,aggregate_id TEXT,payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_workflows_clinic_status ON workflows(clinic_id,status,updated_at DESC); CREATE INDEX IF NOT EXISTS idx_workflow_versions_workflow ON workflow_versions(workflow_id,version DESC); CREATE INDEX IF NOT EXISTS idx_workflow_runs_clinic_status ON workflow_runs(clinic_id,status,created_at DESC); CREATE INDEX IF NOT EXISTS idx_workflow_runs_request ON workflow_runs(clinic_id,request_id) WHERE request_id IS NOT NULL; CREATE INDEX IF NOT EXISTS idx_workflow_step_runs_run ON workflow_step_runs(workflow_run_id,ordinal); CREATE INDEX IF NOT EXISTS idx_workflow_approvals_clinic_status ON workflow_approvals(clinic_id,status,created_at DESC); CREATE INDEX IF NOT EXISTS idx_workflow_events_clinic_created ON workflow_events(clinic_id,created_at DESC);
ALTER TABLE public.workflows ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workflows FORCE ROW LEVEL SECURITY; ALTER TABLE public.workflow_versions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workflow_versions FORCE ROW LEVEL SECURITY; ALTER TABLE public.workflow_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workflow_runs FORCE ROW LEVEL SECURITY; ALTER TABLE public.workflow_step_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workflow_step_runs FORCE ROW LEVEL SECURITY; ALTER TABLE public.workflow_approvals ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workflow_approvals FORCE ROW LEVEL SECURITY; ALTER TABLE public.workflow_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.workflow_events FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS hezqara_workflow_select ON public.workflows; DROP POLICY IF EXISTS hezqara_workflow_insert ON public.workflows; DROP POLICY IF EXISTS hezqara_workflow_update ON public.workflows; CREATE POLICY hezqara_workflow_select ON public.workflows FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_insert ON public.workflows FOR INSERT TO authenticated WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_update ON public.workflows FOR UPDATE TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))) WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS hezqara_workflow_version_select ON public.workflow_versions; DROP POLICY IF EXISTS hezqara_workflow_version_insert ON public.workflow_versions; CREATE POLICY hezqara_workflow_version_select ON public.workflow_versions FOR SELECT TO authenticated USING (workflow_id IN (SELECT id FROM public.workflows WHERE clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)))); CREATE POLICY hezqara_workflow_version_insert ON public.workflow_versions FOR INSERT TO authenticated WITH CHECK (workflow_id IN (SELECT id FROM public.workflows WHERE clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))));
DROP POLICY IF EXISTS hezqara_workflow_run_select ON public.workflow_runs; DROP POLICY IF EXISTS hezqara_workflow_run_insert ON public.workflow_runs; DROP POLICY IF EXISTS hezqara_workflow_run_update ON public.workflow_runs; CREATE POLICY hezqara_workflow_run_select ON public.workflow_runs FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_run_insert ON public.workflow_runs FOR INSERT TO authenticated WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_run_update ON public.workflow_runs FOR UPDATE TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))) WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS hezqara_workflow_step_select ON public.workflow_step_runs; DROP POLICY IF EXISTS hezqara_workflow_step_insert ON public.workflow_step_runs; DROP POLICY IF EXISTS hezqara_workflow_step_update ON public.workflow_step_runs; CREATE POLICY hezqara_workflow_step_select ON public.workflow_step_runs FOR SELECT TO authenticated USING (workflow_run_id IN (SELECT id FROM public.workflow_runs WHERE clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)))); CREATE POLICY hezqara_workflow_step_insert ON public.workflow_step_runs FOR INSERT TO authenticated WITH CHECK (workflow_run_id IN (SELECT id FROM public.workflow_runs WHERE clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)))); CREATE POLICY hezqara_workflow_step_update ON public.workflow_step_runs FOR UPDATE TO authenticated USING (workflow_run_id IN (SELECT id FROM public.workflow_runs WHERE clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)))) WITH CHECK (workflow_run_id IN (SELECT id FROM public.workflow_runs WHERE clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))));
DROP POLICY IF EXISTS hezqara_workflow_approval_select ON public.workflow_approvals; DROP POLICY IF EXISTS hezqara_workflow_approval_insert ON public.workflow_approvals; DROP POLICY IF EXISTS hezqara_workflow_approval_update ON public.workflow_approvals; CREATE POLICY hezqara_workflow_approval_select ON public.workflow_approvals FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_approval_insert ON public.workflow_approvals FOR INSERT TO authenticated WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_approval_update ON public.workflow_approvals FOR UPDATE TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))) WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
DROP POLICY IF EXISTS hezqara_workflow_event_select ON public.workflow_events; DROP POLICY IF EXISTS hezqara_workflow_event_insert ON public.workflow_events; CREATE POLICY hezqara_workflow_event_select ON public.workflow_events FOR SELECT TO authenticated USING (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true))); CREATE POLICY hezqara_workflow_event_insert ON public.workflow_events FOR INSERT TO authenticated WITH CHECK (clinic_id IN (SELECT id FROM public.clinics WHERE clerk_org_id=current_setting('app.clerk_org_id',true)));
REVOKE ALL ON public.workflows,public.workflow_versions,public.workflow_runs,public.workflow_step_runs,public.workflow_approvals,public.workflow_events FROM anon; GRANT SELECT,INSERT,UPDATE ON public.workflows TO authenticated; GRANT SELECT,INSERT ON public.workflow_versions TO authenticated; GRANT SELECT,INSERT,UPDATE ON public.workflow_runs TO authenticated; GRANT SELECT,INSERT,UPDATE ON public.workflow_step_runs TO authenticated; GRANT SELECT,INSERT,UPDATE ON public.workflow_approvals TO authenticated; GRANT SELECT,INSERT ON public.workflow_events TO authenticated;
CREATE OR REPLACE FUNCTION public.reject_workflow_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'workflow history is immutable'; END;$$;
DROP TRIGGER IF EXISTS workflow_event_immutable ON public.workflow_events; CREATE TRIGGER workflow_event_immutable BEFORE UPDATE OR DELETE ON public.workflow_events FOR EACH ROW EXECUTE FUNCTION public.reject_workflow_history_mutation();
